    // 保存原始的 XMLHttpRequest
    const originalOpen = XMLHttpRequest.prototype.open;
    const originalSend = XMLHttpRequest.prototype.send;

    // 重写 XMLHttpRequest 的 open 方法
    XMLHttpRequest.prototype.open = function(method, url) {
        this._url = url; // 保存 URL
        this._method = method; // 保存方法
        originalOpen.apply(this, arguments);
    };

    // 重写 XMLHttpRequest 的 send 方法
    XMLHttpRequest.prototype.send = function() {
        if (this._url && this._method === 'GET' && /collect\/v1\/index\/addiction_prevention_time/.test(this._url)) {
            // 创建自定义响应
            const response = new Response('', { status: 1, statusText: ' "status": 1, "msg": "ok","data": { "play_time": -1, "next_time": -1,"alert_msg": "","real_name": 1, "real_age": 24,"is_visitor": false, "download_app_msg": "\u66f4\u5b8c\u5584\u7684\u529f\u80fd\uff0c\u66f4\u6d41\u7545\u7684\u4f53\u9a8c\uff0c\u66f4\u4e30\u5bcc\u7684\u798f\u5229\u6d3b\u52a8\uff0c\u5c3d\u5728\u6a59\u5149APP\uff01\u70b9\u51fb\u4e0b\u65b9\u6309\u94ae\uff0c\u63a2\u7d22\u65e0\u9650\u53ef\u80fd\uff01", "force_login": 1 }' });
            this.onreadystatechange = () => {
                if (this.readyState === 4) {
                    this.status = response.status;
                    this.statusText = response.statusText;
                    this.responseText = response.responseText;
                }
            };
            this.readyState = 4;
            this.onreadystatechange();
            return;
        }
        originalSend.apply(this, arguments);
    };

