  // 新增：批量加载选中的Gist存档
async loadMultipleGistSaves(gistIds) {
    try {
        const results = [];
        
        for (const gistId of gistIds) {
            try {
                const result = await this.loadFromGist(gistId);
                if (result.success) {
                    results.push({
                        gistId: gistId,
                        success: true,
                        data: result.data,
                        name: result.name,
                        saveCount: result.saveCount
                    });
                } else {
                    results.push({
                        gistId: gistId,
                        success: false,
                        error: result.message
                    });
                }
            } catch (error) {
                results.push({
                    gistId: gistId,
                    success: false,
                    error: error.message
                });
            }
        }
        
        return {
            success: true,
            results: results,
            total: results.length,
            successCount: results.filter(r => r.success).length,
            errorCount: results.filter(r => !r.success).length
        };
    } catch (error) {
        return {
            success: false,
            message: error.message
        };
    }
},

// 新增：重命名Gist存档
async renameGistSave(gistId, newName) {
    try {
        this.checkGitHubToken();
        
        // 先获取现有的Gist数据
        const gist = await this.githubRequest(`${GIST_CONFIG.BASE_URL}/${gistId}`);
        
        if (!gist.files) {
            throw new Error('Gist 中没有文件');
        }

        const oldFilename = Object.keys(gist.files).find(name => name.endsWith('.json'));
        if (!oldFilename) {
            throw new Error('Gist 中没有找到JSON文件');
        }
        
        const newFilename = `${newName}.json`;
        const fileContent = gist.files[oldFilename];
        
        // 更新Gist
        const payload = {
            description: `橙光游戏存档 - ${newName} - ${new Date().toLocaleString()}`,
            files: {
                [newFilename]: {
                    content: fileContent.content
                }
            }
        };
        
        // 如果文件名改变，需要删除旧文件
        if (oldFilename !== newFilename) {
            payload.files[oldFilename] = null;
        }

        const result = await this.githubRequest(`${GIST_CONFIG.BASE_URL}/${gistId}`, {
            method: 'PATCH',
            body: JSON.stringify(payload)
        });

        return {
            success: true,
            gistId: result.id,
            oldName: oldFilename.replace('.json', ''),
            newName: newName,
            html_url: result.html_url
        };
    } catch (error) {
        console.error('重命名Gist失败:', error);
        return { 
            success: false, 
            message: error.message || '重命名Gist失败' 
        };
    }
},

