// 新增：搜索本地存档
    searchLocalSaves(saveData, searchTerm) {
        if (!searchTerm) return saveData;
        
        const searchLower = searchTerm.toLowerCase();
        const filteredData = {};
        
        for (const key in saveData) {
            if (key.startsWith('save')) {
                try {
                    const saveObj = JSON.parse(saveData[key]);
                    const rawName = saveObj.Header?.Name || '未知存档';
                    const normalizedName = this.normalizeSaveName(rawName);
                    
                    if (normalizedName.toLowerCase().includes(searchLower) || 
                        rawName.toLowerCase().includes(searchLower) ||
                        key.toLowerCase().includes(searchLower)) {
                        filteredData[key] = saveData[key];
                    }
                } catch (e) {
                    // 如果解析失败，但key匹配也包含
                    if (key.toLowerCase().includes(searchLower)) {
                        filteredData[key] = saveData[key];
                    }
                }
            }
        }
        
        return filteredData;
    },

