    getSelectedLocalSavesData(selectedKeys) {
        const saveData = {};
        selectedKeys.forEach(key => {
            const value = localStorage.getItem(key);
            if (value) {
                saveData[key] = value;
            }
        });
        return saveData;
    },


    showTempMessage(element, message, duration = 1500) {
        if (!element) {
            console.warn('showTempMessage: element is null or undefined', message);
            return;
        }
        
        try {
            const originalText = element.innerHTML;
            const originalBg = element.style.background;
            
            element.innerHTML = message;
            element.style.background = message.includes('✓') ? '#4CAF50' :
                                     message.includes('✕') ? '#f44336' :
                                     message.includes('ℹ️') ? '#2196F3' : '#9c27b0';
            
            setTimeout(() => {
                if (element) {
                    element.innerHTML = originalText;
                    element.style.background = originalBg;
                }
            }, duration);
        } catch (error) {
            console.error('showTempMessage error:', error);
        }
    },

