    setVariableValue(type, id, value) {
        try {
            const numValue = parseInt(value);
            if (isNaN(numValue)) return false;

            if (type === 'normal' || type === 'additional-normal') {
                tv.system.vars.data[parseInt(id)] = numValue;
            } else if (type === 'ex' || type === 'additional-ex') {
                tv.system.varsEx.data[parseInt(id)] = numValue;
                if (tv.system.varsEx.saveExData) {
                    tv.system.varsEx.saveExData();
                }
            }
            
            return true;
        } catch (error) {
            console.error('设置变量失败:', error);
            return false;
        }
    },

    getVariableValue(type, id) {
        try {
            if (type === 'normal' || type === 'additional-normal') {
                return tv?.system?.vars?.data?.[parseInt(id)] || 0;
            } else if (type === 'ex' || type === 'additional-ex') {
                return tv?.system?.varsEx?.data?.[parseInt(id)] || 0;
            }
            return 0;
        } catch (error) {
            console.error('获取变量值失败:', error);
            return 0;
        }
    },

    modifyChargeAmount(value) {
        try {
            const numValue = parseInt(value);
            if (isNaN(numValue)) {
                return { success: false, message: '请输入有效的数字' };
            }

            const userData = window.getUserData?.() || {};
            ['totalFlower', 'freshFlower', 'realFlower'].forEach(k => {
                userData[k] = numValue;
            });
            
            if (window.updateUserData) {
                window.updateUserData(userData);
            }

            lc = numValue;

            return { 
                success: true, 
                value: numValue,
                message: `累充已设置为 ${numValue}`
            };
        } catch (error) {
            console.error('累充修改失败:', error);
            return { success: false, message: error.message };
        }
    },

    modifyUID(newUid) {
        try {
            if (!window.gb || !gb._instance) {
                return { success: false, message: 'gb._instance 不存在' };
            }
            
            const oldUid = gb._instance.userData?.uid;
                       
            // 修改userData中的uid
            gb._instance.userData.uid = newUid;
            
            // 修改savekey中的uid
            // 修改savekey中的uid（只替换最后一个匹配）
if (gb._instance.savekey) {
    gb._instance.savekey = gb._instance.savekey.replace(new RegExp(`${oldUid}(?!.*${oldUid})`), newUid);
}
            
            // 保存到本地用户列表
            const savedUsers = JSON.parse(localStorage.getItem('savedUsers') || '[]');
            const existingUser = savedUsers.find(u => u.uid === newUid);
            if (!existingUser) {
                const userName = gb._instance.userData.userName || '未知用户';
                savedUsers.push({
                    uid: newUid,
                    userName: userName,
                    lastUsed: new Date().toISOString()
                });
                localStorage.setItem('savedUsers', JSON.stringify(savedUsers));
            }
            // 不需要更新最后使用时间，避免频繁写入
            
            return { 
                success: true, 
                message: 'UID修改成功'
            };
        } catch (error) {
            console.error('UID修改失败:', error);
            return { success: false, message: error.message };
        }
    },

