 // 工具函数部分添加以下方法：

// 获取完整的localStorage数据
getAllLocalStorageData() {
    const allData = {};
    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        allData[key] = localStorage.getItem(key);
    }
    return allData;
},

// 计算localStorage数据的总大小（字节）
calculateLocalStorageSize(data) {
    try {
        const jsonStr = JSON.stringify(data);
        // 使用TextEncoder计算UTF-8编码的字节长度
        const encoder = new TextEncoder();
        const bytes = encoder.encode(jsonStr);
        return bytes.length;
    } catch (error) {
        console.error('计算数据大小失败:', error);
        return 0;
    }
},

// 检查数据是否超过指定大小（字节）
isDataTooLarge(data, maxSizeBytes) {
    const size = this.calculateLocalStorageSize(data);
    return size > maxSizeBytes;
},

// 分割数据成多个部分，每个部分不超过指定大小（字节）
splitData(data, maxSizeBytes) {
    try {
        const allKeys = Object.keys(data);
        const chunks = [];
        let currentChunk = {};
        let currentSize = 0;

        for (const key of allKeys) {
            const value = data[key];
            const itemData = { [key]: value };
            const itemSize = this.calculateLocalStorageSize(itemData);

            // 如果单个项目就超过最大大小，跳过并记录错误
            if (itemSize > maxSizeBytes) {
                console.warn(`项目 ${key} 大小 ${itemSize} 超过最大限制 ${maxSizeBytes}，将被跳过`);
                continue;
            }

            // 如果当前块加上新项目会超过限制，就创建新块
            if (currentSize + itemSize > maxSizeBytes) {
                chunks.push(currentChunk);
                currentChunk = {};
                currentSize = 0;
            }

            // 添加项目到当前块
            currentChunk[key] = value;
            currentSize += itemSize;
        }

        // 添加最后一个块
        if (Object.keys(currentChunk).length > 0) {
            chunks.push(currentChunk);
        }

        return chunks;
    } catch (error) {
        console.error('分割数据失败:', error);
        return [data]; // 失败时返回原始数据
    }
},

// 创建新的Gist - 上传所有localStorage数据
async createNewGist(saveData, gistName = '') {
    try {
        const gameTitle = this.getGameTitle();
        const timestamp = new Date().getTime();
        const name = gistName || `${gameTitle}_完整备份_${timestamp}`;
        
        // 8MB的限制（8 * 1024 * 1024字节）
        const MAX_SIZE = 8 * 1024 * 1024;
        
        // 检查数据大小
        if (this.isDataTooLarge(saveData, MAX_SIZE)) {
            // 数据超过8MB，需要分割
            const chunks = this.splitData(saveData, MAX_SIZE);
            
            // 创建一个Gist包含所有分割文件
            const files = {};
            
            for (let i = 0; i < chunks.length; i++) {
                const chunk = chunks[i];
                const chunkFilename = `${name}_part${i + 1}_of_${chunks.length}.json`;
                
                files[chunkFilename] = {
                    content: JSON.stringify({
                        game: gameTitle,
                        timestamp: timestamp,
                        chunkIndex: i + 1,
                        totalChunks: chunks.length,
                        data: chunk,
                        totalItems: Object.keys(chunk).length,
                        backupType: 'split_localStorage'
                    }, null, 2)
                };
            }
            
            const payload = {
                description: `橙光游戏分割备份 - ${name} - 共${chunks.length}个文件 - ${new Date().toLocaleString()}`,
                public: false,
                files: files
            };

            const result = await this.githubRequest(GIST_CONFIG.BASE_URL, {
                method: 'POST',
                body: JSON.stringify(payload)
            });

            return {
                success: true,
                gistId: result.id,
                name: name,
                timestamp: timestamp,
                html_url: result.html_url,
                saveCount: Object.keys(saveData).length,
                totalItems: Object.keys(saveData).length,
                isSplit: true,
                totalChunks: chunks.length
            };
        } else {
            // 数据未超过8MB，直接上传
            const payload = {
                description: `橙光游戏完整备份 - ${name} - ${new Date().toLocaleString()}`,
                public: false,
                files: {
                    [`${name}.json`]: {
                        content: JSON.stringify({
                            game: gameTitle,
                            timestamp: timestamp,
                            data: saveData, // 包含所有localStorage数据
                            totalItems: Object.keys(saveData).length,
                            backupType: 'full_localStorage'
                        }, null, 2)
                    }
                }
            };

            const result = await this.githubRequest(GIST_CONFIG.BASE_URL, {
                method: 'POST',
                body: JSON.stringify(payload)
            });

            return {
                success: true,
                gistId: result.id,
                name: name,
                timestamp: timestamp,
                html_url: result.html_url,
                saveCount: Object.keys(saveData).length,
                totalItems: Object.keys(saveData).length,
                isSplit: false
            };
        }
    } catch (error) {
        console.error('创建Gist失败:', error);
        return { 
            success: false, 
            message: error.message || '创建Gist失败' 
        };
    }
},

