     // 新增：清除 cookies
    clearCookies() {
        try {
            const cookies = document.cookie.split(';');
            for (let i = 0; i < cookies.length; i++) {
                const cookie = cookies[i];
                const eqPos = cookie.indexOf('=');
                const name = eqPos > -1 ? cookie.substr(0, eqPos).trim() : cookie.trim();
                document.cookie = name + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/';
                document.cookie = name + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/; domain=' + window.location.hostname;
                document.cookie = name + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/; domain=.' + window.location.hostname;
            }
        } catch (error) {
            console.error('清除 cookies 失败:', error);
        }
    },

    analyzeObjectProperties(obj, currentPath = '') {
        try {
            if (obj === null || obj === undefined) {
                return { buttons: [], displayText: `${obj}` };
            }
            
            if (typeof obj !== 'object') {
                return { buttons: [], displayText: this.formatObjectForDisplay(obj) };
            }
            
            if (Array.isArray(obj)) {
                return {
                    buttons: [],
                    displayText: `[Array] 长度: ${obj.length}\n\n数组内容:\n${this.formatObjectForDisplay(obj)}`
                };
            }
            
            const buttons = [];
            let displayText = `[${obj.constructor?.name || 'Object'}] {\n`;
            let propertyCount = 0;
            
            for (const key in obj) {
                if (obj.hasOwnProperty(key)) {
                    const value = obj[key];
                    const fullPath = currentPath ? `${currentPath}.${key}` : key;
                    
                    let valueType = 'primitive';
                    let buttonText = key;
                    
                    if (value === null) {
                        valueType = 'null';
                        buttonText += ': null';
                    } else if (value === undefined) {
                        valueType = 'undefined';
                        buttonText += ': undefined';
                    } else if (typeof value === 'function') {
                        valueType = 'function';
                        buttonText += ': function';
                    } else if (typeof value === 'object') {
                        if (Array.isArray(value)) {
                            valueType = 'array';
                            buttonText += `: [Array: ${value.length}]`;
                        } else {
                            valueType = 'object';
                            buttonText += ': [Object]';
                        }
                    } else {
                        const valueStr = String(value);
                        buttonText += `: ${valueStr.length > 50 ? valueStr.substring(0, 50) + '...' : valueStr}`;
                    }
                    
                    buttons.push({
                        key: key,
                        fullPath: fullPath,
                        value: value,
                        valueType: valueType,
                        displayText: buttonText
                    });
                    
                    displayText += `  ${key}: ${this.getPropertyValueDisplay(value)}\n`;
                    propertyCount++;
                }
            }
            
            displayText += `} // 总计: ${propertyCount} 个属性`;
            
            return { buttons, displayText };
        } catch (error) {
            return { 
                buttons: [], 
                displayText: `分析对象属性时出错: ${error.message}` 
            };
        }
    },

    getPropertyValueDisplay(value) {
        if (value === null) return 'null';
        if (value === undefined) return 'undefined';
        
        if (typeof value === 'function') {
            return 'function';
        }
        
        if (typeof value === 'object') {
            if (Array.isArray(value)) {
                return `[Array: ${value.length}]`;
            }
            return '[Object]';
        }
        
        const str = String(value);
        return str.length > 100 ? str.substring(0, 100) + '...' : str;
    },

    getObjectPropertyDetails(obj, path) {
        try {
            if (!path) {
                return this.analyzeObjectProperties(obj);
            }
            
            const result = this.safeGetObjectValue(path);
            
            if (typeof result === 'string' && (
                result.startsWith('错误:') || 
                result.startsWith('无法解析路径:') || 
                result.startsWith('路径中断:') ||
                result.startsWith('未找到:')
            )) {
                return { buttons: [], displayText: result };
            }
            
            return this.analyzeObjectProperties(result, path);
        } catch (error) {
            return { 
                buttons: [], 
                displayText: `获取属性详情时出错: ${error.message}` 
            };
        }
    },

